type conformanceProvider struct {
	provider      string
	system        string
	model         string
	serverAddress string
	serverPort    int
	responses     []Response
	callCount     int
}

func (p *conformanceProvider) SessionStartMetadata() (string, string) {
	return p.provider, p.model
}

func (p *conformanceProvider) ChatStartMetadata() (string, string, int) {
	return p.system, p.serverAddress, p.serverPort
}

func (p *conformanceProvider) Chat(ctx context.Context, messages []Message, tools []ToolDef, opts Options) (Response, error) {
	if ctx.Err() != nil {
		return Response{}, ctx.Err()
	}
	if p.callCount >= len(p.responses) {
		return Response{}, errors.New("no more responses")
	}
	resp := p.responses[p.callCount]
	p.callCount++
	return resp, nil
}

func TestRun_CONTRACT001SpanConformance(t *testing.T) {
	recorder := tracetest.NewSpanRecorder()
	tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(recorder))
	tel := telemetry.New(telemetry.Config{TracerProvider: tp})

	provider := &conformanceProvider{
		provider:      "lmstudio",
		system:        "openai",
		model:         "gpt-4o",
		serverAddress: "api.openai.com",
		serverPort:    443,
		responses: []Response{
			{
				ToolCalls: []ToolCall{
					{ID: "call-1", Name: "read", Arguments: json.RawMessage(`{"path":"main.go"}`)},
				},
				Usage: TokenUsage{Input: 11, Output: 9, CacheRead: 2, CacheWrite: 1, Total: 20},
				Model: "gpt-4o",
				Attempt: &AttemptMetadata{
					ProviderName:   "lmstudio",
					ProviderSystem: "openai",
					Route:          "default",
					RequestedModel: "gpt-4o",
					ResponseModel:  "gpt-4o",
					ResolvedModel:  "gpt-4o",
					ServerAddress:  "api.openai.com",
					ServerPort:     443,
					Cost: &CostAttribution{
						Source: CostSourceUnknown,
					},
				},
			},
			{
				Content: "done",
				Usage:   TokenUsage{Input: 10, Output: 5, Total: 15},
				Model:   "gpt-4o",
				Attempt: &AttemptMetadata{
					ProviderName:   "lmstudio",
					ProviderSystem: "openai",
					RequestedModel: "gpt-4o",
					ResponseModel:  "gpt-4o",
					ResolvedModel:  "gpt-4o",
					ServerAddress:  "api.openai.com",
					ServerPort:     443,
					Cost: &CostAttribution{
						Source: CostSourceUnknown,
					},
				},
			},
		},
	}

	readTool := &mockTool{name: "read", result: "package main\n"}
	result, err := Run(context.Background(), Request{
		Prompt:    "read main.go and finish",
		Provider:  provider,
		Tools:     []Tool{readTool},
		Telemetry: tel,
	})
	require.NoError(t, err)
	assert.Equal(t, StatusSuccess, result.Status)

	ended := recorder.Ended()
	require.Len(t, ended, 4)

	root := spanByName(t, ended, "invoke_agent fizeau")
	chatOne := spanByAttrInt(t, ended, telemetry.KeyTurnIndex, 1, telemetry.KeyAttemptIndex, 1)
	chatTwo := spanByAttrInt(t, ended, telemetry.KeyTurnIndex, 2, telemetry.KeyAttemptIndex, 1)
	toolSpan := spanByToolExec(t, ended, 1, 1, "read")

	assert.Equal(t, trace.SpanKindInternal, root.SpanKind())
	assert.Equal(t, trace.SpanKindClient, chatOne.SpanKind())
	assert.Equal(t, trace.SpanKindClient, chatTwo.SpanKind())
	assert.Equal(t, trace.SpanKindInternal, toolSpan.SpanKind())

	assert.Equal(t, root.SpanContext().TraceID(), chatOne.SpanContext().TraceID())
	assert.Equal(t, root.SpanContext().TraceID(), chatTwo.SpanContext().TraceID())
	assert.Equal(t, root.SpanContext().TraceID(), toolSpan.SpanContext().TraceID())
	assert.Equal(t, root.SpanContext().SpanID(), chatOne.Parent().SpanID())
	assert.Equal(t, root.SpanContext().SpanID(), chatTwo.Parent().SpanID())
	assert.Equal(t, root.SpanContext().SpanID(), toolSpan.Parent().SpanID())

	assert.Equal(t, result.SessionID, attrString(t, root.Attributes(), telemetry.KeySessionID))
	assert.Equal(t, result.SessionID, attrString(t, chatOne.Attributes(), telemetry.KeySessionID))
	assert.Equal(t, result.SessionID, attrString(t, chatTwo.Attributes(), telemetry.KeySessionID))
	assert.Equal(t, result.SessionID, attrString(t, toolSpan.Attributes(), telemetry.KeySessionID))
	assert.Equal(t, result.SessionID, attrString(t, root.Attributes(), telemetry.KeyConversationID))
	assert.Equal(t, result.SessionID, attrString(t, chatOne.Attributes(), telemetry.KeyConversationID))
	assert.Equal(t, result.SessionID, attrString(t, chatTwo.Attributes(), telemetry.KeyConversationID))
	assert.Equal(t, result.SessionID, attrString(t, toolSpan.Attributes(), telemetry.KeyConversationID))

	assert.Equal(t, "invoke_agent", attrString(t, root.Attributes(), telemetry.KeyOperationName))
	assert.Equal(t, "fizeau", attrString(t, root.Attributes(), telemetry.KeyServiceName))
	assert.Equal(t, "fizeau", attrString(t, root.Attributes(), telemetry.KeyHarnessName))
	assert.Equal(t, "Fizeau", attrString(t, root.Attributes(), telemetry.KeyAgentName))
	assert.Equal(t, "chat", attrString(t, chatOne.Attributes(), telemetry.KeyOperationName))
	assert.Equal(t, "chat", attrString(t, chatTwo.Attributes(), telemetry.KeyOperationName))
	assert.Equal(t, "execute_tool", attrString(t, toolSpan.Attributes(), telemetry.KeyOperationName))

	assert.Equal(t, "lmstudio", attrString(t, chatOne.Attributes(), telemetry.KeyProviderName))
	assert.Equal(t, "openai", attrString(t, chatOne.Attributes(), telemetry.KeyProviderSystem))
	assert.Equal(t, "default", attrString(t, chatOne.Attributes(), telemetry.KeyProviderRoute))
	assert.Equal(t, "gpt-4o", attrString(t, chatOne.Attributes(), telemetry.KeyRequestModel))
	assert.Equal(t, "gpt-4o", attrString(t, chatOne.Attributes(), telemetry.KeyResponseModel))
	assert.Equal(t, "gpt-4o", attrString(t, chatOne.Attributes(), telemetry.KeyProviderModelResolved))
	assert.Equal(t, "api.openai.com", attrString(t, chatOne.Attributes(), telemetry.KeyServerAddress))
	assert.Equal(t, int64(443), attrInt(t, chatOne.Attributes(), telemetry.KeyServerPort))

	assert.Equal(t, "read", attrString(t, toolSpan.Attributes(), telemetry.KeyToolName))
	assert.Equal(t, "function", attrString(t, toolSpan.Attributes(), telemetry.KeyToolType))
	assert.Equal(t, "call-1", attrString(t, toolSpan.Attributes(), telemetry.KeyToolCallID))
	assert.Equal(t, int64(1), attrInt(t, toolSpan.Attributes(), telemetry.KeyTurnIndex))
	assert.Equal(t, int64(1), attrInt(t, toolSpan.Attributes(), telemetry.KeyToolExecutionIndex))

	assertNoContentCaptureAttrs(t, root.Attributes())
	assertNoContentCaptureAttrs(t, chatOne.Attributes())
	assertNoContentCaptureAttrs(t, chatTwo.Attributes())
	assertNoContentCaptureAttrs(t, toolSpan.Attributes())
}

func TestRun_CONTRACT001CostPrecedence(t *testing.T) {
	recorder := tracetest.NewSpanRecorder()
	tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(recorder))
	configuredCost := 0.20
	reportedCost := 0.05
	tel := telemetry.New(telemetry.Config{
		TracerProvider: tp,
		Pricing: telemetry.RuntimePricing{
			"openai": {
				"gpt-4o": {
					Amount:     &configuredCost,
					Currency:   "USD",
					PricingRef: "openai/gpt-4o",
				},
			},
		},
	})

	provider := &conformanceProvider{
		provider:      "lmstudio",
		system:        "openai",
		model:         "gpt-4o",
		serverAddress: "api.openai.com",
		serverPort:    443,
		responses: []Response{
			{
				Content: "done",
				Usage:   TokenUsage{Input: 12, Output: 3, Total: 15},
				Model:   "gpt-4o",
				Attempt: &AttemptMetadata{
					ProviderName:   "lmstudio",
					ProviderSystem: "openai",
					RequestedModel: "gpt-4o",
					ResponseModel:  "gpt-4o",
					ResolvedModel:  "gpt-4o",
					ServerAddress:  "api.openai.com",
					ServerPort:     443,
					Cost: &CostAttribution{
						Source:   CostSourceProviderReported,
						Amount:   &reportedCost,
						Currency: "USD",
					},
				},
			},
		},
	}

	result, err := Run(context.Background(), Request{
		Prompt:    "report cost",
		Provider:  provider,
		Telemetry: tel,
	})
	require.NoError(t, err)
	assert.Equal(t, StatusSuccess, result.Status)
	assert.InDelta(t, reportedCost, result.CostUSD, 1e-9)

	ended := recorder.Ended()
	require.Len(t, ended, 2)

	chatSpans := spansWithOperation(t, ended, "chat")
	require.Len(t, chatSpans, 1)
	assert.Equal(t, "openai", attrString(t, chatSpans[0].Attributes(), telemetry.KeyProviderSystem))
}

func TestRun_CONTRACT001MixedKnownCostProvenance(t *testing.T) {
	recorder := tracetest.NewSpanRecorder()
	tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(recorder))
	providerCost := 0.01
	configuredCost := 0.02
	tel := telemetry.New(telemetry.Config{
		TracerProvider: tp,
		Pricing: telemetry.RuntimePricing{
			"openai": {
				"gpt-4o": {
					Amount:     &configuredCost,
					Currency:   "USD",
					PricingRef: "openai/gpt-4o",
				},
			},
		},
	})

	readTool := &mockTool{name: "read", result: "package main\n"}
	provider := &conformanceProvider{
		provider:      "lmstudio",
		system:        "openai",
		model:         "gpt-4o",
		serverAddress: "api.openai.com",
		serverPort:    443,
		responses: []Response{
			{
				ToolCalls: []ToolCall{

		},
		Duration: 250 * time.Millisecond,
		Err:      errors.New("boom"),
	})

	var rm metricdata.ResourceMetrics
	require.NoError(t, reader.Collect(context.Background(), &rm))
	require.NotEmpty(t, rm.ScopeMetrics)
	assert.Equal(t, "fizeau", rm.ScopeMetrics[0].Scope.Name)

	durationMetric := findMetric(t, rm, "gen_ai.client.operation.duration")
	durationPoints := histogramFloatPoints(t, durationMetric)
	require.Len(t, durationPoints, 1)
	assert.Equal(t, uint64(1), durationPoints[0].Count)
	assert.InDelta(t, 0.25, durationPoints[0].Sum, 1e-9)
	assert.Equal(t, "fizeau", metricAttrString(t, durationPoints[0].Attributes, KeyServiceName))
	assert.Equal(t, "lmstudio", metricAttrString(t, durationPoints[0].Attributes, KeyProviderName))
	assert.Equal(t, "openai", metricAttrString(t, durationPoints[0].Attributes, KeyProviderSystem))
	assert.Equal(t, "gpt-4o", metricAttrString(t, durationPoints[0].Attributes, KeyRequestModel))
	assert.Equal(t, "gpt-4o", metricAttrString(t, durationPoints[0].Attributes, KeyResponseModel))
	assert.Equal(t, "gpt-4o", metricAttrString(t, durationPoints[0].Attributes, KeyProviderModelResolved))
	assert.True(t, strings.Contains(metricAttrString(t, durationPoints[0].Attributes, KeyErrorType), "errorString"))

	tokenMetric := findMetric(t, rm, "gen_ai.client.token.usage")
	tokenPoints := histogramIntPoints(t, tokenMetric)
	require.Len(t, tokenPoints, 2)

	inputPoint := pointByTokenType(t, tokenPoints, "input")
	assert.Equal(t, uint64(1), inputPoint.Count)
	assert.Equal(t, int64(11), inputPoint.Sum)
	assert.Equal(t, "lmstudio", metricAttrString(t, inputPoint.Attributes, KeyProviderName))
	assert.Equal(t, "input", metricAttrString(t, inputPoint.Attributes, KeyTokenType))
	assert.True(t, strings.Contains(metricAttrString(t, inputPoint.Attributes, KeyErrorType), "errorString"))

	outputPoint := pointByTokenType(t, tokenPoints, "output")
	assert.Equal(t, uint64(1), outputPoint.Count)
	assert.Equal(t, int64(9), outputPoint.Sum)
	assert.Equal(t, "output", metricAttrString(t, outputPoint.Attributes, KeyTokenType))
}

func findSpan(t *testing.T, ended []sdktrace.ReadOnlySpan, name string) sdktrace.ReadOnlySpan {
	t.Helper()

	for _, span := range ended {
		if span.Name() == name {
			return span
		}
	}

	require.Failf(t, "span not found", "missing span %q", name)
	var zero sdktrace.ReadOnlySpan
	return zero
}

func attrString(t *testing.T, attrs []attribute.KeyValue, key string) string {
	t.Helper()

	for _, attr := range attrs {
		if string(attr.Key) == key {
			return attr.Value.AsString()
		}
	}

	require.Failf(t, "attribute not found", "missing %q", key)
	return ""
}

func attrInt(t *testing.T, attrs []attribute.KeyValue, key string) int64 {
	t.Helper()

	for _, attr := range attrs {
		if string(attr.Key) == key {
			return attr.Value.AsInt64()
		}
	}

	require.Failf(t, "attribute not found", "missing %q", key)
	return 0
}

func findMetric(t *testing.T, rm metricdata.ResourceMetrics, name string) metricdata.Metrics {
	t.Helper()

	for _, scope := range rm.ScopeMetrics {
		for _, metric := range scope.Metrics {
			if metric.Name == name {
				return metric
			}
		}
	}

	require.Failf(t, "metric not found", "missing %q", name)
	return metricdata.Metrics{}
}

func histogramFloatPoints(t *testing.T, metric metricdata.Metrics) []metricdata.HistogramDataPoint[float64] {
	t.Helper()

	hist, ok := metric.Data.(metricdata.Histogram[float64])
	require.Truef(t, ok, "unexpected metric type %T", metric.Data)
	return hist.DataPoints
}

func histogramIntPoints(t *testing.T, metric metricdata.Metrics) []metricdata.HistogramDataPoint[int64] {
	t.Helper()

	hist, ok := metric.Data.(metricdata.Histogram[int64])
	require.Truef(t, ok, "unexpected metric type %T", metric.Data)
	return hist.DataPoints
}

func pointByTokenType(t *testing.T, points []metricdata.HistogramDataPoint[int64], tokenType string) metricdata.HistogramDataPoint[int64] {
	t.Helper()

	for _, point := range points {
		if metricAttrString(t, point.Attributes, KeyTokenType) == tokenType {
			return point
		}
	}

	require.Failf(t, "metric point not found", "missing token type %q", tokenType)
	return metricdata.HistogramDataPoint[int64]{}
}

func captureTelemetryLogs(t *testing.T) (*bytes.Buffer, func()) {
	t.Helper()

	var buf bytes.Buffer
	prev := slog.Default()
	logger := slog.New(slog.NewTextHandler(&buf, &slog.HandlerOptions{Level: slog.LevelWarn}))
	slog.SetDefault(logger)
	return &buf, func() {
		slog.SetDefault(prev)
	}
}

func metricAttrString(t *testing.T, attrs attribute.Set, key string) string {
	t.Helper()

	value, ok := attrs.Value(attribute.Key(key))
	if !ok {
		require.Failf(t, "metric attribute not found", "missing %q", key)
		return ""
	}
	return value.AsString()
}

	return New(Config{})
}

func (r *runtime) Shutdown(ctx context.Context) {
	if r.shutdown == nil {
		return
	}
	if err := r.shutdown(ctx); err != nil {
		slog.Warn("telemetry: shutdown failed", "err", err)
	}
}

func (r *runtime) StartInvokeAgent(ctx context.Context, attrs InvokeAgentSpan) (context.Context, trace.Span) {
	merged := mergeInvokeAgent(ctx, attrs)
	spanName := spanName(operationInvokeAgent, merged.HarnessName)
	ctx, span := r.tracer.Start(ctx, spanName,
		trace.WithSpanKind(trace.SpanKindInternal),
		trace.WithAttributes(runAttributes(merged)...),
	)
	ctx = context.WithValue(ctx, ctxKey{}, runState{invoke: merged})
	return ctx, span
}

func (r *runtime) StartChat(ctx context.Context, attrs ChatSpan) (context.Context, trace.Span) {
	merged := mergeChat(ctx, attrs)
	spanName := spanName(operationChat, merged.RequestedModel)
	opts := []trace.SpanStartOption{
		trace.WithSpanKind(trace.SpanKindClient),
		trace.WithAttributes(chatAttributes(merged)...),
	}
	if !merged.StartTime.IsZero() {
		opts = append(opts, trace.WithTimestamp(merged.StartTime))
	}
	ctx, span := r.tracer.Start(ctx, spanName, opts...)
	return ctx, span
}

func (r *runtime) StartExecuteTool(ctx context.Context, attrs ExecuteToolSpan) (context.Context, trace.Span) {
	merged := mergeTool(ctx, attrs)
	spanName := spanName(operationExecuteTool, merged.ToolName)
	ctx, span := r.tracer.Start(ctx, spanName,
		trace.WithSpanKind(trace.SpanKindInternal),
		trace.WithAttributes(toolAttributes(merged)...),
	)
	return ctx, span
}

func (r *runtime) RecordChatMetrics(ctx context.Context, attrs ChatSpan, metrics ChatMetrics) {
	if r == nil {
		return
	}

	metricAttrs := chatMetricAttributes(attrs, metrics)
	if r.chatDuration != nil {
		r.chatDuration.Record(ctx, metrics.Duration.Seconds(), metric.WithAttributes(metricAttrs...))
	}
	if r.chatTokenUsed == nil {
		return
	}

	if metrics.Usage.Input > 0 {
		r.chatTokenUsed.Record(ctx, int64(metrics.Usage.Input), metric.WithAttributes(tokenMetricAttributes(metricAttrs, "input")...))
	}
	if metrics.Usage.Output > 0 {
		r.chatTokenUsed.Record(ctx, int64(metrics.Usage.Output), metric.WithAttributes(tokenMetricAttributes(metricAttrs, "output")...))
	}
}

func (r *runtime) ResolveCost(providerSystem, resolvedModel string) (Cost, bool) {
	if r == nil {
		return Cost{}, false
	}

	systemPricing, ok := r.pricing[providerSystem]
	if !ok {
		return Cost{}, false
	}

	cost, ok := systemPricing[resolvedModel]
	if !ok {
		return Cost{}, false
	}

	// Require at least a pre-computed amount or per-MTok rates to be meaningful.
	if cost.Amount == nil && cost.InputPerMTok == 0 && cost.OutputPerMTok == 0 {
		return Cost{}, false
	}

	if cost.Source == "" {
		cost.Source = "configured"
	}
	if cost.Currency == "" {
		cost.Currency = "USD"
	}
	if cost.PricingRef == "" {
		cost.PricingRef = fmt.Sprintf("%s/%s", providerSystem, resolvedModel)
	}
	return cost, true
}

func mergeInvokeAgent(ctx context.Context, attrs InvokeAgentSpan) InvokeAgentSpan {
	state := stateFromContext(ctx)
	merged := state.invoke
	merged.HarnessName = firstNonEmpty(attrs.HarnessName, merged.HarnessName)
	merged.HarnessVersion = firstNonEmpty(attrs.HarnessVersion, merged.HarnessVersion)
	merged.SessionID = firstNonEmpty(attrs.SessionID, merged.SessionID)
	merged.ParentSessionID = firstNonEmpty(attrs.ParentSessionID, merged.ParentSessionID)
	merged.ConversationID = firstNonEmpty(attrs.ConversationID, merged.ConversationID)
	merged.AgentName = firstNonEmpty(attrs.AgentName, merged.AgentName)
	merged.AgentVersion = firstNonEmpty(attrs.AgentVersion, merged.AgentVersion)
	merged.AgentID = firstNonEmpty(attrs.AgentID, merged.AgentID)
	if merged.ConversationID == "" {
		merged.ConversationID = merged.SessionID
	}
	return merged
}

